{
  "items": [
    {
      "name": "Polynomial.coeff_bdd_of_roots_le",
      "module_name": "Mathlib.Topology.Algebra.Polynomial",
      "kind": "theorem",
      "type": "∀ {F : Type u_3} {K : Type u_4} [inst : CommRing F] [inst_1 : NormedField K] {B : ℝ} {d : ℕ} (f : F →+* K)\n  {p : Polynomial F},\n  p.Monic →\n    (Polynomial.map f p).Splits →\n      p.natDegree ≤ d →\n        (∀ z ∈ (Polynomial.map f p).roots, ‖z‖ ≤ B) →\n          ∀ (i : ℕ), ‖(Polynomial.map f p).coeff i‖ ≤ max B 1 ^ d * ↑(d.choose (d / 2))"
    },
    {
      "name": "SzemerediRegularity.initialBound",
      "module_name": "Mathlib.Combinatorics.SimpleGraph.Regularity.Bound",
      "kind": "definition",
      "type": "ℝ → ℕ → ℕ"
    },
    {
      "name": "Behrend.roth_lower_bound",
      "module_name": "Mathlib.Combinatorics.Additive.AP.Three.Behrend",
      "kind": "theorem",
      "type": "∀ {N : ℕ}, ↑N * Real.exp (-4 * √(Real.log ↑N)) ≤ ↑(rothNumberNat N)"
    },
    {
      "name": "Polynomial.coeff_le_of_roots_le",
      "module_name": "Mathlib.Topology.Algebra.Polynomial",
      "kind": "theorem",
      "type": "∀ {F : Type u_3} {K : Type u_4} [inst : CommRing F] [inst_1 : NormedField K] {p : Polynomial F} {f : F →+* K} {B : ℝ}\n  (i : ℕ),\n  p.Monic →\n    (Polynomial.map f p).Splits →\n      (∀ z ∈ (Polynomial.map f p).roots, ‖z‖ ≤ B) →\n        ‖(Polynomial.map f p).coeff i‖ ≤ B ^ (p.natDegree - i) * ↑(p.natDegree.choose i)"
    },
    {
      "name": "Polynomial.supDegree_eq_natDegree",
      "module_name": "Mathlib.Algebra.Polynomial.Degree.Support",
      "kind": "theorem",
      "type": "∀ {R : Type u} [inst : Semiring R] (p : Polynomial R), AddMonoidAlgebra.supDegree id p.toFinsupp = p.natDegree"
    },
    {
      "name": "Polynomial.cauchyBound_zero",
      "module_name": "Mathlib.Analysis.Polynomial.CauchyBound",
      "kind": "theorem",
      "type": "∀ {K : Type u_1} [inst : NormedDivisionRing K], Polynomial.cauchyBound 0 = 1"
    },
    {
      "name": "MvPolynomial.schwartz_zippel_sup_sum",
      "module_name": "Mathlib.Algebra.MvPolynomial.SchwartzZippel",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : CommRing R] [IsDomain R] [inst_2 : DecidableEq R] {n : ℕ} {p : MvPolynomial (Fin n) R},\n  p ≠ 0 →\n    ∀ (S : Fin n → Finset R),\n      ↑{x ∈ Fintype.piFinset fun i => S i | (MvPolynomial.eval x) p = 0}.card / ∏ i, ↑(S i).card ≤\n        p.support.sup fun s => ∑ i, ↑(s i) / ↑(S i).card"
    },
    {
      "name": "RootPairing.chainTopCoeff_eq_sSup",
      "module_name": "Mathlib.LinearAlgebra.RootSystem.Chain",
      "kind": "theorem",
      "type": "∀ {ι : Type u_1} {R : Type u_2} {M : Type u_3} {N : Type u_4} [inst : Finite ι] [inst_1 : CommRing R]\n  [inst_2 : CharZero R] [inst_3 : IsDomain R] [inst_4 : AddCommGroup M] [inst_5 : Module R M] [inst_6 : AddCommGroup N]\n  [inst_7 : Module R N] {P : RootPairing ι R M N} [inst_8 : P.IsCrystallographic] {i j : ι},\n  LinearIndependent R ![P.root i, P.root j] →\n    RootPairing.chainTopCoeff i j = sSup {k | P.root j + k • P.root i ∈ Set.range ⇑P.root}"
    }
  ]
}
